MQL:
db.documents.aggregate([
  { $project: { _id: 0, document_id: 1, title: 1, metric_pairs: { $objectToArray: "$metrics" } } },
  { $unwind: "$metric_pairs" },
  { $match: { "metric_pairs.k": { $in: ["weight", "priority"] } } },
  { $group: {
      _id: "$metric_pairs.k",
      avg_value: { $avg: { $toDouble: "$metric_pairs.v" } }
  } },
  { $sort: { avg_value: -1 } },
  { $group: {
      _id: null,
      ranked: { $push: { k: "$_id", avg_value: "$avg_value" } }
  } },
  { $project: {
      _id: 0,
      top_metric: { $arrayElemAt: ["$ranked", 0] }
  } }
])
